ns16:scriptTask.ns16:script:
tw.local.odcRequest.stepLog ={};
tw.local.odcRequest.stepLog.startTime = new Date();
tw.local.odcRequest.stepLog.step      =  tw.epv.ScreenNames.closureACT05;
tw.local.odcRequest.appInfo.stepName = tw.epv.ScreenNames.closureACT05;

tw.local.actionconditions = {};
tw.local.actionconditions.screenName     = tw.epv.ScreenNames.closureACT05;

tw.local.flexCubeContractNoVIS = "READONLY";

tw.local.closeContract=false;	
tw.local.actionconditions.submiteToHub = tw.local.odcRequest.submitToHub;
console.log("actionConditions : ",tw.local.actionconditions);

 tw.local.errorMessage ="";
 var mandatoryTriggered = false;
 tw.system.coachValidation.clearValidationErrors();
/************************************************************************************************************************
/*-------------------------------------------------- All Section's Validation ------------------------------------------
************************************************************************************************************************/
//-------------------------------------------------DC TEMPLATE VALIDATION -------------------------------------------
mandatory(tw.local.odcRequest.stepLog.action, "tw.local.odcRequest.stepLog.action");
mandatory(tw.local.odcRequest.ReversalReason.closureReason , "tw.local.odcRequest.ReversalReason.closureReason");

if(tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.returnToTradeFo || tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.returnToInitiator)
{
	mandatory(tw.local.odcRequest.stepLog.returnReason , "tw.local.odcRequest.stepLog.returnReason");
	maxLength(tw.local.odcRequest.stepLog.returnReason , "tw.local.odcRequest.stepLog.returnReason", 80 , "Shouldn't be more than 80 character" , "Return reason: " + "Shouldn't be more than 80 character" );
}	
	
if( tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.approveRequest ){
	if(!tw.local.odcRequest.BasicDetails.flexCubeContractNo  && !tw.local.odcRequest.BasicDetails.flexCubeContractNo2 ){
		addError("tw.local.odcRequest.BasicDetails.flexCubeContractNo","Please make sure contract number is available before calling the close integration")
	}
}


function mandatory(field , fieldName)
{
	if (field == null || field == undefined )
	{
		addError(fieldName , tw.resource.ValidationMessages.ThisFieldIsMandatory , tw.resource.ValidationMessages.MandatoryFields , true);
		mandatoryTriggered = true;
		return false;
	}
	else
	{			
		switch (typeof field)
		{
			case "string":
				if (field.trim() != undefined && field.trim() != null && field.trim().length == 0)
				{
					addError(fieldName , tw.resource.ValidationMessages.ThisFieldIsMandatory , tw.resource.ValidationMessages.MandatoryFields , true);
					mandatoryTriggered = true;
					return false;
				}
				break;
			case "number":
				if (field == 0.0)
				{
					addError(fieldName , tw.resource.ValidationMessages.ThisFieldIsMandatory , tw.resource.ValidationMessages.MandatoryFields , true);
					mandatoryTriggered = true;
					return false;
				}
				break;
	
			default:
				
				// VALIDATE DATE OBJECT
				if( field && field.getTime && isFinite(field.getTime()) ) {}
				
				else
				{
					addError(fieldName , tw.resource.ValidationMessages.ThisFieldIsMandatory , tw.resource.ValidationMessages.MandatoryFields , true);
					mandatoryTriggered = true;
					return false;	
				}
		}
	}
	return true;
}

function addError(fieldName , controlMessage , validationMessage , fromMandatory)
{
	tw.system.coachValidation.addValidationError(fieldName, controlMessage);
	fromMandatory && mandatoryTriggered ? "" : tw.local.errorMessage += "<li>" + validationMessage + "</li>";
}
function maxLength(field , fieldName , len , controlMessage , validationMessage)
{
	if (field.length > len)
	{
		addError(fieldName , controlMessage , validationMessage);
		return false;
	}
	return true;
}
maxLength(tw.local.odcRequest.stepLog.comment , "tw.local.odcRequest.stepLog.comment", 500 , "Shouldn't be more than 500 character" , "Comment: " + "Shouldn't be more than 500 character" );
 tw.local.errorMessage ="";

if(tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.approveRequest)
{
	
	tw.local.lastAction = "";
}

else if(tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.returnToTradeFo)
{
	tw.local.lastAction = tw.epv.CreationActions.returnToTradeFo;
}
else{
	tw.local.lastAction = tw.epv.CreationActions.returnToInitiator;
}

tw.local.odcRequest.appInfo.status    ="" + tw.epv.Status.InExecution;
tw.local.odcRequest.appInfo.subStatus = "" + tw.epv.Status.pendingExecutionHubClosureReview;

ns16:extensionElements.ns2:preAssignmentScript:
var contNum3 = tw.local.odcRequest.BasicDetails.flexCubeContractNo3;
var contNum2 = tw.local.odcRequest.BasicDetails.flexCubeContractNo2;
var contNum1 = tw.local.odcRequest.BasicDetails.flexCubeContractNo;

tw.local.lastFlexContractNum = contNum2 || contNum1;

ns16:extensionElements.ns2:postAssignmentScript:
console.group("<<CLOSE CONTRACT>>");
console.log("CLOSE CONTRACT REQ");
console.log(tw.local.xmlRequest2);
console.log("CLOSE CONTRACT RES");
console.log( tw.local.xmlResponse2 );
console.groupEnd();

if(tw.local.isSuccessful == false){
	var msg ="Close Contract Integration Failed";
	var items = tw.local.messageList || [];
	tw.local.errorVis = "editable";
	
	if(!!tw.local.errorMsg){
		tw.local.errorMessage = msg + '<br>' + `<ul>${tw.local.errorMsg}</ul>`;
	}
	else if (items && items.length > 0){
		var listItems = items.map(item => `<li>${item}</li>`).join('');
		tw.local.errorMessage = msg + '<br>' + `<ul>${listItems}</ul>`;
	}else{
		tw.local.errorMessage = msg;	
	}
}
else{
tw.local.closeContract=true;	
}
